async function main(): Promise<number> {
    const args = parseArgs(process.argv.slice(2));
    const models = (args.models ?? args.model ?? DEFAULT_JEV_MODEL)
        .split(",")
        .map((m) => m.trim())
        .filter((m) => m !== "");
