// Input tokens billed for the same state with 1, 3 and 11 questions, per model.
import { resolveConfig } from "../../src/config.ts";
import { nodeHost } from "../../src/host/node-host.ts";
import { buildState, QUESTIONS } from "../../src/judge/bash-risk-judge.ts";
import { tryEvaluate } from "../../src/judge/jev-client.ts";
import { withModel } from "../../scripts/script-support.ts";
const host = nodeHost({ env: { ...process.env, HOOK_JEV_ENABLE: "1" } });
const config = resolveConfig(host);
const state = buildState("git reset --hard HEAD~3", "/home/u/proj");
for (const model of ["perplexity/pplx-decider-v1.2", "perplexity/pplx-decider-flash-v1.2", "liquid/d1", "liquid/d1-ultra", "typesafe-ai/jev"]) {
    const row = [model.padEnd(36)];
    for (const n of [1, 3, QUESTIONS.length]) {
        const { evaluation, error } = await tryEvaluate(state, QUESTIONS.slice(0, n), withModel(config, model), host);
        const u = evaluation?.raw.usage as Record<string, unknown> | undefined;
        row.push(`${n}q=${u?.inputTokens ?? u?.input_tokens ?? error ?? "?"}`.padEnd(10));
    }
    console.log(row.join(" "));
}
EOF
fnox exec -- bun scratchpad/clef-bench/usage-per-question.ts

